//! The characters a terminal was measured to draw wider than xfx counts them.
//!
//! Generated by `scripts/drawn-wider/sweep.sh` on 2026-11-08: every Unicode scalar
//! but the C0 and C1 controls and the surrogates -- 1,111,999 of them,
//! assigned, private-use and unassigned alike -- printed alone between two
//! markers, `[` and `]`, on tmux 3.7b (a private server, the cursor column
//! read back with a cursor-position report) and on libghostty-vt 1.3.2-HEAD-+0f7cd84b8 (grapheme
//! clustering on, the cursor column read through its C API), and set against
//! xfx's own count of the same three characters (`super::wrap::width`, less
//! the two markers), with unicode-width 0.2.2 and unicode-segmentation
//! 1.13.3 (Unicode 17.0.0 and 17.0.0).
//! A table measured against one count is wrong against another, so the tests
//! below fail when either crate moves; run the sweep again then.
//!
//! Every scalar was measured, so this is an allowlist read the other way: a
//! scalar not here was drawn by both terminals at xfx's count or narrower, and
//! one here -- 43 scalars in 10 ranges, 41 wider in
//! tmux and 2 in libghostty-vt -- is named wherever it stands
//! (`super::approval_view`), unless it is inside a sequence measured whole.
//! Most of them xfx counts as no cells and names on that count already; these
//! it counts as a cell or more:
//!
//! * `U+261D`: xfx 1, tmux 2, libghostty-vt 1
//! * `U+26F9`: xfx 1, tmux 2, libghostty-vt 1
//! * `U+270C`-`U+270D`: xfx 1, tmux 2, libghostty-vt 1
//! * `U+2E3A`-`U+2E3B`: xfx 1, tmux 1, libghostty-vt 2
//! * `U+1F3CB`-`U+1F3CC`: xfx 1, tmux 2, libghostty-vt 1
//! * `U+1F574`-`U+1F575`: xfx 1, tmux 2, libghostty-vt 1
//! * `U+1F590`: xfx 1, tmux 2, libghostty-vt 1

/// Whether a terminal was measured drawing `character` alone wider than xfx
/// counts it.
pub(crate) fn drawn_wider(character: char) -> bool {
    let code = u32::from(character);
    DRAWN_WIDER
        .binary_search_by(|&(first, last)| {
            if last < code {
                std::cmp::Ordering::Less
            } else if first > code {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// The measured ranges, first and last code point, in order.
#[rustfmt::skip]
const DRAWN_WIDER: [(u32, u32); 10] = [
    (0x02065, 0x02065), (0x0261d, 0x0261d), (0x026f9, 0x026f9), (0x0270c, 0x0270d), (0x02e3a, 0x02e3b),
    (0x0fe0f, 0x0fe0f), (0x1f3cb, 0x1f3cc), (0x1f574, 0x1f575), (0x1f590, 0x1f590), (0xe0002, 0xe001f),
];

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_the_sweeps() {
        assert!(DRAWN_WIDER.windows(2).all(|pair| pair[0].1 + 1 < pair[1].0));
        let scalars: u32 = DRAWN_WIDER
            .iter()
            .map(|&(first, last)| last - first + 1)
            .sum();
        assert_eq!(scalars, 43);
    }

    #[test]
    fn the_count_is_the_one_the_sweep_measured_against() {
        assert_eq!(unicode_width::UNICODE_VERSION, (17, 0, 0));
        assert_eq!(unicode_segmentation::UNICODE_VERSION, (17, 0, 0));
        let lock = include_str!("../../Cargo.lock");
        for pinned in [
            "name = \"unicode-width\"\nversion = \"0.2.2\"",
            "name = \"unicode-segmentation\"\nversion = \"1.13.3\"",
        ] {
            assert!(
                lock.contains(pinned),
                "re-run scripts/drawn-wider/sweep.sh: {pinned}"
            );
        }
    }

    /// xfx's count of every scalar the sweep measures, for
    /// `scripts/drawn-wider/sweep.sh`: one hexadecimal code point per line of
    /// `XFX_DRAWN_WIDER_LIST` in, `hex cells` per line of
    /// `XFX_DRAWN_WIDER_OUT` out.
    #[test]
    #[ignore = "run by scripts/drawn-wider/sweep.sh"]
    fn xfx_counts() {
        let list = std::env::var("XFX_DRAWN_WIDER_LIST").expect("XFX_DRAWN_WIDER_LIST");
        let out = std::env::var("XFX_DRAWN_WIDER_OUT").expect("XFX_DRAWN_WIDER_OUT");
        let mut counts = String::new();
        for code in std::fs::read_to_string(list).expect("the list").lines() {
            let value = u32::from_str_radix(code, 16).expect("a hexadecimal code point");
            let character = char::from_u32(value).expect("a scalar");
            let cells = i32::from(super::super::wrap::width(&format!("[{character}]"))) - 2;
            counts.push_str(&format!("{code} {cells}\n"));
        }
        std::fs::write(&out, counts).expect("the counts");
        let versions = format!(
            "{:?};{:?}\n",
            unicode_width::UNICODE_VERSION,
            unicode_segmentation::UNICODE_VERSION
        );
        std::fs::write(format!("{out}.versions"), versions).expect("the versions");
    }
}
